node --input-type=module -e "
async function fetchYear(y){
  const res=await fetch('https://www.ssa.gov/cgi-bin/netcomp.cgi?year='+y);
  const html=await res.text();
  const rows=[...html.matchAll(/<tr>\\s*<td[^>]*>\\$?([0-9,.]+(?:\\.[0-9]+)?)\\s*(?:???|-|&mdash;|???)\\s*([0-9,.]+|and over)<\\/td>\\s*<td[^>]*>([0-9,]+)<\\/td>\\s*<td[^>]*>[0-9,]+<\\/td>\\s*<td[^>]*>[0-9.]+<\\/td>\\s*<td[^>]*>\\$?([0-9,.]+)<\\/td>\\s*<td[^>]*>\\$?([0-9,.]+)<\\/td>/gi)];
  // fallback simpler: number, avg from table lines
  const simple=[...html.matchAll(/<td[^>]*>\\s*([0-9,]{4,})\\s*<\\/td>\\s*<td[^>]*>\\s*[0-9,.]+\\s*<\\/td>\\s*<td[^>]*>\\s*[0-9.]+\\s*<\\/td>\\s*<td[^>]*>\\s*\\$?([0-9,.]+\\.[0-9]+)\\s*<\\/td>\\s*<td[^>]*>\\s*\\$?([0-9,.]+\\.[0-9]+)\\s*<\\/td>/g)];
  // Actually extract all numeric table cells from distribution section
  const start=html.indexOf('Distribution of wage earners');
  const chunk=html.slice(start, start+200000);
  const cells=[...chunk.matchAll(/<td[^>]*>([^<]*)<\\/td>/gi)].map(m=>m[1].replace(/,/g,'').trim());
  const bins=[];
  // rows are 6 cells: interval, number, cumul, pct, aggregate, average
  for(let i=0;i<cells.length-5;i++){
    const n=Number(cells[i+1]);
    const avg=Number(cells[i+5].replace(/[\$]/g,''));
    if(Number.isFinite(n)&&n>1000&&Number.isFinite(avg)&&avg>0&&cells[i].match(/[0-9]/)){
      // verify cumul looks numeric
      const cumul=Number(cells[i+2]);
      if(Number.isFinite(cumul)&&cumul>=n){ bins.push([n,avg]); i+=5; }
    }
  }
  // dedupe weird parses: keep first coherent sequence summing near N
  let best=[]; let bestDiff=1e18;
  for(let starti=0;starti<Math.min(5,bins.length);starti++){
    let sum=0; const seq=[];
    for(let j=starti;j<bins.length;j++){ sum+=bins[j][0]; seq.push(bins[j]); if(sum>2e8) break; }
    const N=seq.reduce((s,b)=>s+b[0],0);
    // SSA N around 160-180m
    const diff=Math.abs(N-170e6);
    if(diff<bestDiff && seq.length>40){ bestDiff=diff; best=seq; }
  }
  const N=best.reduce((s,b)=>s+b[0],0);
  const q=N/5; let idx=0; let wLeft=best[0][0]; let a=best[0][1];
  const means=[];
  for(let qi=0;qi<5;qi++){
    let need=q, sum=0;
    while(need>1e-6){
      const take=Math.min(need,wLeft);
      sum+=take*a; need-=take; wLeft-=take;
      if(wLeft<1e-6){ idx++; if(idx>=best.length)break; wLeft=best[idx][0]; a=best[idx][1]; }
    }
    means.push(Math.round(sum/q));
  }
  const medianMatch=html.match(/median wage[^$]*\\$([0-9,.]+)/i);
  const avgMatch=html.match(/raw average wage[\\s\\S]*?\\$([0-9,.]+)/i);
  return {y,N,means,median:medianMatch&&medianMatch[1],avg:avgMatch&&avgMatch[1],bins:best.length};
}
const years=[2019,2020,2021,2022,2023,2024];
for(const y of years){
  try{ console.log(JSON.stringify(await fetchYear(y))); }
  catch(e){ console.log(y, String(e)); }
}
"
